style.css:
/* 全局字体：中文 PingFang SC；日文假名 Hiragino W3 */

/* 中文汉字、常用中文标点 */
@font-face {
  font-family: "UserChinese";
  src: local("PingFang SC");
  font-style: normal;
  font-weight: normal;
  unicode-range: U+3000-303F, U+3400-4DBF, U+4E00-9FFF, U+F900-FAFF, U+FE10-FE1F, U+FE30-FE4F, U+FF00-FFEF;
}

/* 平假名、片假名、半角片假名 */
@font-face {
  font-family: "UserJapanese";
  src: local("Hiragino Kaku Gothic ProN W3");
  font-style: normal;
  font-weight: normal;
  unicode-range: U+3040-309F, U+30A0-30FF, U+31F0-31FF, U+FF66-FF9F;
}

/* 将字体应用到通常的文本元素，避开图标与代码 */
body,
p,
span,
a,
li,
div,
td,
th,
label,
button,
input,
textarea,
select,
option,
h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: "UserJapanese", "UserChinese", system-ui, sans-serif !important;
}

/* 代码保持等宽 */
code,
pre,
kbd,
samp {
  font-family: "Cascadia Mono", Consolas, monospace !important;
}
